225	void ASTColumnsExceptTransformer::transform(ASTs & nodes) const
226	{
227	    std::set<String> expected_columns;
228	    if (!pattern)
229	    {
230	        for (const auto & child : children)
231	            expected_columns.insert(child->as<const ASTIdentifier &>().name());
232	
233	        for (auto it = nodes.begin(); it != nodes.end();)
234	        {
235	            if (const auto * id = it->get()->as<ASTIdentifier>())
236	            {
237	                auto expected_column = expected_columns.find(id->shortName());
238	                if (expected_column != expected_columns.end())
239	                {
240	                    expected_columns.erase(expected_column);
241	                    it = nodes.erase(it);
242	                    continue;
243	                }
244	            }
245	            ++it;
246	        }
247	    }
248	    else
249	    {
250	        auto regexp = getMatcher();
251	
252	        for (auto it = nodes.begin(); it != nodes.end();)
253	        {
254	            if (auto * id = it->get()->as<ASTIdentifier>())
255	            {
256	                if (RE2::PartialMatch(id->shortName(), *regexp))
257	                {
258	                    it = nodes.erase(it);
259	                    continue;
260	                }
261	            }
262	            ++it;
263	        }
264	    }
265	
266	    if (is_strict && !expected_columns.empty())
267	    {
268	        String expected_columns_str;
269	        std::for_each(expected_columns.begin(), expected_columns.end(),
270	            [&](String x) { expected_columns_str += (" " + x) ; });
271	
272	        throw Exception(ErrorCodes::NO_SUCH_COLUMN_IN_TABLE, "Columns transformer EXCEPT expects following column(s) :{}",
273	            expected_columns_str);
274	    }
275	}
