327	/// There would be columns in normal form & column aliases after translation. Column & column alias would be normalized in QueryNormalizer.
328	void translateQualifiedNames(ASTPtr & query, const ASTSelectQuery & select_query, const NameSet & source_columns_set,
329	                             const TablesWithColumns & tables_with_columns)
330	{
331	    LogAST log;
