333	    TranslateQualifiedNamesVisitor visitor(visitor_data, log.stream());
334	    visitor.visit(query);
335	
336	    /// This may happen after expansion of COLUMNS('regexp').
337	    if (select_query.select()->children.empty())
338	        throw Exception(ErrorCodes::EMPTY_LIST_OF_COLUMNS_QUERIED, "Empty list of columns in SELECT query");
339	}
