341	bool hasArrayJoin(const ASTPtr & ast)
342	{
343	    if (const ASTFunction * function = ast->as<ASTFunction>())
344	        if (function->name == "arrayJoin")
345	            return true;
346	
347	    for (const auto & child : ast->children)
348	        if (!child->as<ASTSelectQuery>() && hasArrayJoin(child))
349	            return true;
350	
351	    return false;
352	}
